        def wrapper(*args, **kwargs):
            last_exception = None
            for attempt in range(times):
                try:
                    return fn(*args, **kwargs)
                except exceptions as e:
                    last_exception = e
                    if attempt < times - 1:
                        if delays is None:
                            delay = 1
                        else:
                            if attempt < len(delays):
                                delay = delays[attempt]
                            else:
                                delay = delays[-1]
                        sleep(delay)
            if last_exception is not None:
                raise last_exception
        return wrapper
    return decorator
