import time
from retrying import retry

def test_times_is_total_attempts():
    calls = 0
    @retry(times=3)
    def func():
        nonlocal calls
        calls += 1
        raise ValueError("fail")

    with pytest.raises(ValueError, match="fail"):
        func()
    assert calls == 3

def test_times_less_than_one_raises_value_error():
    with pytest.raises(ValueError, match="times must be at least 1"):
        @retry(times=0)
        def func():
            pass

def test_only_specified_exceptions_trigger_retry():
    calls = 0
    @retry(times=3, exceptions=(ValueError,))
    def func(exc_type):
        nonlocal calls
        calls += 1
        raise exc_type("fail")

    # Test ValueError (should retry)
    with pytest.raises(ValueError, match="fail"):
        func(ValueError)
    assert calls == 3

    # Test RuntimeError (should NOT retry)
    calls = 0
    @retry(times=3, exceptions=(ValueError,))
    def func2(exc_type):
        nonlocal calls
        calls += 1
        raise exc_type("fail")

    with pytest.raises(RuntimeError, match="fail"):
        func2(RuntimeError)
    assert calls == 1

def test_last_exception_is_reraised():
    calls = 0
    @retry(times=3, exceptions=(ValueError,))
    def func():
        nonlocal calls
        calls += 1
        if calls == 1:
            raise ValueError("first fail")
        elif calls == 2:
            raise ValueError("second fail")
        else:
            raise ValueError("third fail")

    with pytest.raises(ValueError, match="third fail"):
        func()

def test_delays_list():
    sleep_calls = []
    def mock_sleep(seconds):
        sleep_calls.append(seconds)

    calls = 0
    @retry(times=3, delays=[0.1, 0.5], sleep=mock_sleep)
    def func():
        nonlocal calls
        calls += 1
        raise ValueError("fail")

    with pytest.raises(ValueError, match="fail"):
        func()

    assert calls == 3
    assert sleep_calls == [0.1, 0.5]

def test_delays_shorter_than_needed():
    sleep_calls = []
    def mock_sleep(seconds):
        sleep_calls.append(seconds)

    calls = 0
    @retry(times=4, delays=[0.1], sleep=mock_sleep)
    def func():
        nonlocal calls
        calls += 1
        raise ValueError("fail")

    with pytest.raises(ValueError, match="fail"):
        func()

    assert calls == 4
    assert sleep_calls == [0.1, 0.1, 0.1]

def test_delays_none():
    sleep_calls = []
    def mock_sleep(seconds):
        sleep_calls.append(seconds)

    calls = 0
    @retry(times=3, delays=None, sleep=mock_sleep)
    def func():
        nonlocal calls
        calls += 1
        raise ValueError("fail")

    with pytest.raises(ValueError, match="fail"):
        func()

    assert calls == 3
    assert sleep_calls == [1, 1]

def test_never_sleep_after_final_failed_attempt():
    sleep_calls = []
    def mock_sleep(seconds):
        sleep_calls.append(seconds)

    calls = 0
    @retry(times=3, sleep=mock_sleep)
    def func():
        nonlocal calls
        calls += 1
        raise ValueError("fail")

    with pytest.raises(ValueError, match="fail"):
        func()

    assert calls == 3
    assert len(sleep_calls) == 2

def test_keeps_name_and_doc():
    @retry(times=3)
    def my_function():
        """This is a docstring."""
        pass

    assert my_function.__name__ == "my_function"
    assert my_function.__doc__ == "This is a docstring."

def test_no_sleep_on_success():
    sleep_calls = []
    def mock_sleep(seconds):
        sleep_calls.append(seconds)

    calls = 0
    @retry(times=3, sleep=mock_sleep)
    def func():
        nonlocal calls
        calls += 1
        if calls < 3:
            raise ValueError("fail")
        return "success"

    assert func() == "success"
    assert calls == 3
    assert sleep_calls == [1, 1]

def test_no_sleep_on_first_try_success():
    sleep_calls = []
    def mock_sleep(seconds):
        sleep_calls.append(seconds)

    calls = 0
    @retry(times=3, sleep=mock_sleep)
    def func():
        nonlocal calls
        calls += 1
        return "success"

    assert func() == "success"
    assert calls == 1
    assert sleep_calls == []

def test_exceptions_as_single_exception():
    calls = 0
    @retry(times=2, exceptions=ValueError)
    def func():
        nonlocal calls
        calls += 1
        raise ValueError("fail")

    with pytest.raises(ValueError, match="fail"):
        func()
    assert calls == 2
